const caseAliases: Record<string, string> = {
  freedom: 'year', rules: 'decision', fear: 'risk', attention: 'attention', eliminate: 'eliminate', inbox: 'inbox',
  delegate: 'delegate', market: 'market', demand: 'validate', remote: 'remote', exit: 'exit', travel: 'travel',
  meaning: 'modes', decision: 'decision', profit: 'profit', experiment: 'validate', education: 'learning', resources: 'resources',
}

const shifts: Record<string, [string, string]> = {
  cash: ['A booked sale means I can spend.', 'Separate sales, cleared funds and obligations.'], offer: ['The feature list explains the offer.', 'The outcome and delivery terms explain it.'], market: ['Better execution can fix any market.', 'Demand, access and ability to serve matter too.'], value: ['Cost determines what the buyer will pay.', 'The buyer compares an outcome with alternatives.'], service: ['Helping only counts if it returns a favor.', 'Bounded help can be valuable on its own.'], ideas: ['Evaluate the first idea immediately.', 'Generate alternatives before comparing them.'], outcome: ['The requested feature is the goal.', 'The changed decision or result is the goal.'], friction: ['A sale is success; delivery comes later.', 'The promise includes the operating path.'], scarcity: ['Pressure is a useful sales tool.', 'A quantity limit must be real.'], urgency: ['Every offer needs a countdown.', 'A date matters only when time changes the offer.'], bonus: ['More included items mean more value.', 'Each addition should remove a real obstacle.'], risk: ['A guarantee can promise anything.', 'A promise must be fair and fulfillable.'], position: ['A clever name creates demand.', 'A clear name helps the right buyer recognize fit.'], bet: ['Confidence is enough to justify the stake.', 'Exposure should match evidence and affordable loss.'], careerfit: ['A title or ranking can choose for me.', 'Fit is a hypothesis updated by real work.'], impact: ['Good intentions prove a good result.', 'Outcomes and unintended effects need evidence.'], problem: ['The most visible problem is the priority.', 'Compare scale, neglect and a credible path.'], prioritize: ['A score settles the decision.', 'A score exposes assumptions to examine.'], career: ['Only direct work can make a difference.', 'Trace direct and enabling paths to outcomes.'], capital: ['I must maximize impact immediately.', 'Useful capability can expand future contribution.'], plan: ['A plan should predict the future.', 'A plan should guide and update the next step.'], interview: ['Employers should infer my strengths.', 'A clear case connects truthful evidence to their need.'], community: ['Contacts are valuable because of their status.', 'Reciprocal work builds useful relationships.'], reflection: ['I must know before writing the plan.', 'The plan can show what remains unknown.'], decision: ['My first preference is the most reliable signal.', 'Check assumptions, reversibility and counterevidence.'], skills: ['Improvement requires many simultaneous habits.', 'One practiced behavior can be observed and adjusted.'], learning: ['More input will make the choice clear.', 'A question makes learning targeted and usable.'], resources: ['Collecting resources equals progress.', 'A resource should close a named gap.'], attention: ['More available hours guarantee focus.', 'Attention needs a chosen task and fewer cues.'], autopilot: ['Automatic behavior is always bad.', 'Keep routines that serve the intention.'], capacity: ['I can hold every open loop in mind.', 'Externalize decisions so attention can reason.'], hyperfocus: ['Productivity means touching every task.', 'One bounded priority gets room to finish.'], distraction: ['Only outside noise breaks concentration.', 'Notice the cues and interruptions I can redesign.'], habit: ['Drift means I lack discipline.', 'Check challenge, energy and environment first.'], wander: ['Every minute must have a visible output.', 'Bounded open attention can connect useful ideas.'], energy: ['A break is another task to optimize.', 'A restorative pause should fit my actual energy.'], modes: ['Imagining change means I have made progress.', 'Connect reflection to a scheduled action.'], start: ['Readiness must come before action.', 'A small, safe start creates information.'], ask: ['Interest is enough evidence.', 'A clear ask distinguishes praise from commitment.'], validate: ['Building proves that buyers want it.', 'Demand deserves evidence before a large build.'], trend: ['A growing category guarantees a business.', 'Market movement is one signal to investigate.'], customers: ['A few sales prove the whole model.', 'Early payments answer one demand question.'], audience: ['Reach is the same as relevance.', 'Repeated attention from the right group matters.'], email: ['An email list is only for pitching.', 'Useful context can make an offer relevant.'], metrics: ['Clicks mean the launch worked.', 'Trace every step from attention to net sales.'], year: ['More growth will improve ordinary life.', 'Design the days first, then the operation.'], excuses: ['Confidence will arrive before practice.', 'A small next step can expose the real blocker.'], sequence: ['Build first, then find a customer.', 'Answer demand questions in order.'], restart: ['A result settles my ability.', 'Use each result to choose the next experiment.'],
}

function chapterSource(chapter: BooksChapter): Source[] {
  return chapter.beats?.length ? chapter.beats : chapter.sittings
}

function makeCase(plan: { title: string }, family: string): BookLearningPlan['caseStudy'] {
  const recipe = cases[family] ?? cases[caseAliases[family]] ?? cases.learning
  return {
    label: 'Practice scenario',
    title: `Try the idea: ${plan.title}`,
    situation: recipe.situation,
    question: recipe.question,
    choices: recipe.options.map((label, index) => ({ label, consequence: recipe.consequences[index], reason: recipe.reasons[index] })),
    recommended: 1,
    boundary: recipe.boundary,
  }
}

/** Each loaded chapter has a curated mechanism and a source passage anchor. Coaching never grades comprehension. */
export function getBookLearningPlan(chapter: BooksChapter): BookLearningPlan {
  const items = chapterSource(chapter)
  const authoredPlan = authored[`${chapter.part}:${chapter.index}`]
  const workweekPlan = chapter.part === 5 ? workweek.get(`${chapter.part}:${chapter.index}`) : undefined
  const sourcePlan = authoredPlan ?? workweekPlan
  const sourceId = authoredPlan?.source ?? workweekPlan?.anchor
  const source = items.find((item) => item.id === sourceId) ?? items.find((item) => item.kind === 'idea' && item.bodyEn.trim()) ?? items.find((item) => item.bodyEn.trim()) ?? items[0]
  const principleTitle = sourcePlan?.title ?? source?.titleEn ?? chapter.titleEn
  const explanation = sourcePlan?.explanation ?? `Read “${source?.titleEn ?? chapter.titleEn}” as a claim to inspect: name what changes, how that could affect a real decision, and which condition would make the idea fail. Use the source passage to find evidence and limits before applying it.`
  const family = sourcePlan?.family ?? 'learning'
  const [defaultBefore, defaultAfter] = shifts[family] ?? shifts.learning
  const trySitting = items.find((item) => item.kind === 'try' && item.bodyEn.trim())
  const actionPrompt = trySitting
    ? `Use the chapter exercise “${trySitting.titleEn}” on a real, low-risk decision. Write your prediction, the action you take and what evidence would change your mind.`
    : `Apply “${principleTitle}” to one current decision. Write the smallest next action, your prediction and the evidence you will review.`
  const mindset = sourcePlan && 'before' in sourcePlan
    ? { before: sourcePlan.before, after: sourcePlan.after, why: `The chapter’s example about “${source?.titleEn ?? principleTitle}” supports a more precise question: what would have to be true for this mechanism to work?`, prompt: `Where could “${principleTitle}” change a real choice you face—and what limit would you keep?` }
    : { before: defaultBefore, after: defaultAfter, why: `The source passage “${source?.titleEn ?? principleTitle}” is an example to examine, not a rule to copy. Check the conditions before carrying the idea into your own situation.`, prompt: `Where could “${principleTitle}” change a real choice you face—and what limit would you keep?` }
  return {
    principle: { title: principleTitle, explanation, sourceSittingId: source?.id ?? '' },
    caseStudy: makeCase(sourcePlan ?? { title: principleTitle }, family),
    mindset,
    teachBackPrompt: `Without reopening the source, explain “${principleTitle}”: what changes, why might it work, and what condition could make it fail?`,
    actionPrompt,
    reviewPrompt: `Tomorrow, recall the mechanism and its limit in “${principleTitle}.” What evidence from your action changed or strengthened your view?`,
  }
}
